var UserConnection = Get<UserConnection>("UserConnection");
Guid lineDetailId = Get<Guid>("LineDetail");
string lineDetailList = Get<string>("LineDetailList");
bool sendRequest = Get<bool>("SendRequest");
string reservationId = Get<string>("ReservationId");
bool withIMEI = Get<bool>("WithIMEI");

var service = new DMSService(UserConnection);
var unreserve = new UnreserveStock(UserConnection);

try {
	if (lineDetailId != Guid.Empty) {
		var param = unreserve.GetParam(lineDetailId);
		Set("Request", JsonConvert.SerializeObject(param, Formatting.Indented));

		if (sendRequest) {
			var response = service.UnreserveStock(param).GetAwaiter().GetResult();
			Set("Response", JsonConvert.SerializeObject(response, Formatting.Indented));
		}
	} else if (!string.IsNullOrEmpty(reservationId)) {
		var param = withIMEI
			? unreserve.GetParamWithIMEI(reservationId)
			: unreserve.GetParam(reservationId);
		Set("Request", JsonConvert.SerializeObject(param, Formatting.Indented));

		if (sendRequest) {
			var response = service.UnreserveStock(param).GetAwaiter().GetResult();
			Set("Response", JsonConvert.SerializeObject(response, Formatting.Indented));
		}
	}
} catch (Exception e) {
	Set("Message", e.Message);
}

return true;
